<form method="post">@csrf<div class="grid-2"><section class="panel"><div class="panel-head"><h2>Payment details</h2></div><div class="panel-body"><div class="row g-3"><div class="col-md-6"><label>Payment date</label><input type="date" name="payment_date" value="{{old('payment_date',today()->format('Y-m-d'))}}" class="form-control" required></div><div class="col-md-6"><label>Amount received</label><input type="number" step="0.01" min="0.01" name="amount" id="payment_amount" value="{{old('amount')}}" class="form-control" required></div><div class="col-md-6"><label>Payment mode</label><select name="method" id="payment_method" class="form-select" required><option value="">Select</option>@foreach(['cash'=>'Cash','upi'=>'UPI','bank_transfer'=>'Bank transfer','card'=>'Card','cheque'=>'Cheque','other'=>'Other'] as $value=>$label)<option value="{{$value}}" @selected(old('method')===$value)>{{$label}}</option>@endforeach</select></div><div class="col-md-6"><label>Reference / transaction ID</label><input name="reference" class="form-control" value="{{old('reference')}}"><small class="help">Required for UPI, bank, card and cheque.</small></div><div class="col-12"><label>Deposit account</label><input name="deposit_account" class="form-control" value="{{old('deposit_account')}}" placeholder="Cash counter, bank account or clearing account"></div><div class="col-12"><label>Notes</label><textarea name="notes" class="form-control" rows="3">{{old('notes')}}</textarea></div></div></div></section>
<aside><section class="panel"><div class="panel-head"><h2>Allocate payment</h2><button type="button" id="auto_allocate" class="btn btn-sm btn-outline-primary">Auto allocate</button></div><div class="table-responsive"><table class="table"><thead><tr><th>Invoice</th><th class="text-end">Due</th><th style="width:115px">Allocate</th></tr></thead><tbody>@forelse($openInvoices as $invoice)<tr><td><div class="name">{{$invoice->invoice_number}}</div><div class="meta">Due {{$invoice->due_date?->format('d M Y')?:'—'}}</div></td><td class="money" data-balance="{{$invoice->balance_due}}">₹{{number_format((float)$invoice->balance_due,2)}}</td><td><input type="number" min="0" step="0.01" max="{{$invoice->balance_due}}" name="allocations[{{$invoice->id}}]" value="{{old('allocations.'.$invoice->id,0)}}" class="form-control allocation"></td></tr>@empty<tr><td colspan="3" class="empty">No open invoices. This payment will be held as an advance.</td></tr>@endforelse</tbody></table></div><div class="panel-body border-top"><div class="d-flex justify-content-between"><span class="meta">Allocated</span><strong id="allocated_total">₹0.00</strong></div><div class="d-flex justify-content-between mt-2"><span class="meta">Unallocated advance</span><strong id="advance_total">₹0.00</strong></div><div class="d-flex gap-2 mt-4"><a href="{{route('admin.membership-accounts.member',$user)}}" class="btn btn-outline-secondary btn-ma">Cancel</a><button class="btn btn-primary btn-ma flex-grow-1">Post & issue receipt</button></div></div></section></aside></div></form></div>
<script>document.addEventListener('DOMContentLoaded',()=>{const amount=document.getElementById('payment_amount'),inputs=[...document.querySelectorAll('.allocation')],allocated=document.getElementById('allocated_total'),advance=document.getElementById('advance_total');function calc(){const total=inputs.reduce((s,i)=>s+(parseFloat(i.value)||0),0),received=parseFloat(amount.value)||0;allocated.textContent='₹'+total.toFixed(2);advance.textContent='₹'+Math.max(0,received-total).toFixed(2);advance.classList.toggle('text-danger',total>received)}[amount,...inputs].forEach(i=>i.addEventListener('input',calc));document.getElementById('auto_allocate').addEventListener('click',()=>{let left=parseFloat(amount.value)||0;inputs.forEach(i=>{const due=parseFloat(i.max)||0,take=Math.min(left,due);i.value=take.toFixed(2);left-=take});calc()});calc()})</script>
